// One clean row per holding, ready for a spreadsheet. Every row has the same columns.
const today = new Date().toISOString().slice(0, 10);
return $input.all().map((item) => {
  const h = item.json;
  return { json: {
    date: today,
    symbol: h.symbol,
    quantity: h.quantity ?? '',
    price: h.price ?? '',
    value: h.value ?? '',
    day_change_pct: h.day_change_pct ?? '',
    cost: h.cost ?? '',
    profit_loss: h.pl ?? '',
    profit_loss_pct: h.pl_pct ?? '',
    weight_pct: h.weight_pct ?? '',
    rsi: h.rsi ?? '',
    flags: (h.flags || []).join(', '),
    note: h.error || '',
  } };
});
